// Frozen contract (Phase 0). Mirrors docs/PRD.md "Data model and stack".
// Change requests go to the lead; agents do not edit this file.

/** offer: a claimed place's time-limited deal, "20% off this week" (DECISIONS.md 2026-10-22, claims). */
export type PinType = 'civic' | 'event' | 'ask' | 'area' | 'offer'
export type PostedAs = 'neighbour' | 'place' | 'ptp'
export type PinStatus = 'active' | 'hidden'
export type AreaTopic = 'water' | 'power' | 'traffic' | 'road' | 'festival'

/** All times are epoch milliseconds. */
export interface Pin {
  id: string
  type: PinType
  title: string
  body?: string | null
  lat: number
  lng: number
  placeId?: string | null
  placeName?: string | null
  /** Small avatar for postedAs "place" (Google place photo URI). */
  placePhotoUri?: string | null
  /** Events only. */
  startsAt?: number | null
  /** Area updates: end time. Events: optional end time (else startsAt + 2h is assumed). Offers: when the offer ends. */
  endsAt?: number | null
  /** Area updates only: first published end time; endsAt > endsAtOriginal shows "Extended". */
  endsAtOriginal?: number | null
  /** Area updates only: circle radius in metres. */
  radiusM?: number | null
  /** Area updates only. */
  topic?: AreaTopic | null
  createdAt: number
  /** Posting device ID. Stored for abuse tracing, NEVER shown. */
  createdBy: string
  lastSupportAt?: number | null
  postedAs: PostedAs
  status: PinStatus
  seed?: boolean
  /** Where a curated item came from (a public listing or a news report). Shown on the card's source line. */
  sourceUrl?: string | null
  /** Short words for the source line, e.g. "Listing on allevents.in". */
  sourceLabel?: string | null
  /** The item's own image (the listing's banner, the report's photo). Never a stand-in picture. */
  imageUrl?: string | null
  /** A photo the poster added (stored on its own in pinPhotos/{pinId}, fetched when the detail opens). */
  hasPhoto?: boolean
}

/** A posted photo: a JPEG data URL the phone shrank to about 800 px (DECISIONS.md 2026-10-23). */
export const PHOTO_MAX_CHARS = 400_000
export const PHOTO_PREFIX = 'data:image/jpeg;base64,'

/** Area updates are pins with type "area", postedAs "ptp". They never appear in the feed or as markers. */
export type AreaUpdate = Pin & { type: 'area'; postedAs: 'ptp' }

export interface Support {
  /** Document id = `${pinId}_${deviceId}` */
  id: string
  pinId: string
  deviceId: string
  createdAt: number
}

/** live = shown to everyone; under_review = posted, waiting for the team (every new comment starts here). */
export type CommentStatus = 'live' | 'under_review'

/** What a neighbour saw at a pin (DECISIONS.md 2026-10-22, PRD extension). Always shown as "Neighbour". */
export interface Comment {
  id: string
  pinId: string
  /** At most COMMENT_MAX characters. */
  text: string
  createdAt: number
  /** Posting device ID. Stored for abuse tracing, NEVER shown. */
  deviceId: string
  status: CommentStatus
  seed?: boolean
}

export const COMMENT_MAX = 280

export interface NewComment {
  pinId: string
  text: string
}

/** pending = paid (mock checkout) and waiting for the team; active = the device may post as the place. */
export type ClaimStatus = 'pending' | 'active'

/** A business claiming its Google place (DECISIONS.md 2026-10-22). Document id = placeId: one claim per place. */
export interface Claim {
  id: string
  placeId: string
  placeName: string
  /** Claiming device. Stored for the team, NEVER shown. */
  deviceId: string
  status: ClaimStatus
  plan: 'monthly'
  priceUsd: number
  /** Prototype: set by the mock checkout. No card is ever taken. */
  paid: boolean
  createdAt: number
}

export const CLAIM_PRICE_USD = 100

export interface NewClaim {
  placeId: string
  placeName: string
}

export interface LatLng {
  lat: number
  lng: number
}

export interface Bounds {
  north: number
  south: number
  east: number
  west: number
}

/** Filter chip values. "all" = no chip selected. "places" isolates the Google places layer. */
export type Filter = 'all' | 'civic' | 'event' | 'ask' | 'places'

/** A real place from Google Places (New) Nearby Search, shown as a quiet context dot on the map. */
export interface NearbyPlace {
  id: string
  name: string
  lat: number
  lng: number
  /** Google's primary type in words, e.g. "Cafe", "Park". */
  kind: string | null
  /** True / false when Google returned opening hours, null when unknown. */
  openNow: boolean | null
}

export type SheetHeight = 'peek' | 'half' | 'full'

/**
 * Input for creating a pin. Default: posted as neighbour (civic, event, ask). asPlace: posted as the place, only
 * for a device holding an ACTIVE claim on placeId (repo and rules check), and only event or offer.
 */
export interface NewPin {
  type: 'civic' | 'event' | 'ask' | 'offer'
  title: string
  lat: number
  lng: number
  placeId?: string | null
  placeName?: string | null
  startsAt?: number | null
  /** Offers only: when it ends. */
  endsAt?: number | null
  asPlace?: boolean
  /** Optional photo: a JPEG data URL, at most PHOTO_MAX_CHARS (lib/photo shrinkPhoto makes it). */
  photo?: string | null
}

/** Data access contract. Implemented by src/data (Firestore + in-memory mock). */
export interface Repo {
  /** Resolves once the device has an id (anonymous auth uid, or local id in mock). */
  init(): Promise<{ deviceId: string }>
  /** Live list of active pins (all types incl. area). bounds may be ignored by an impl for 30-200 pins. */
  subscribePins(bounds: Bounds | null, cb: (pins: Pin[]) => void): () => void
  subscribeSupports(cb: (supports: Support[]) => void): () => void
  createPin(input: NewPin): Promise<Pin>
  /** One support per device per pin; a second call removes it. Returns the new state. */
  toggleSupport(pinId: string): Promise<{ supported: boolean }>
  /** Live list of LIVE comments only (under_review never reaches other devices). */
  subscribeComments(cb: (comments: Comment[]) => void): () => void
  /** Posts as this device with status "under_review". Rejects empty or over-long text. */
  addComment(input: NewComment): Promise<Comment>
  /** Every claim (pending and active), so a place shows as claimed. */
  subscribeClaims(cb: (claims: Claim[]) => void): () => void
  /** Mock checkout then a "pending" claim for this device. Rejects when the place is already claimed. */
  claimPlace(input: NewClaim): Promise<Claim>
  /** A pin's posted photo (JPEG data URL), or null. Shown straight away to everyone (human's choice, 2026-10-23). */
  getPhoto(pinId: string): Promise<string | null>
}
